import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import test from "node:test";
import { generateProblem, templates } from "../src/math/engine";

/**
 * `version-gate-legacy-fractions.json` holds, per bumped template, the first
 * 32 hex digits of sha256 over the newline-joined sha256 digests of the full
 * problem JSON for seeds `gate-legacy:0` … `gate-legacy:199`, generated by
 * main before these templates changed (#1985 tree) at version 1.
 */
const legacyGolden = JSON.parse(
  readFileSync(
    new URL("./fixtures/version-gate-legacy-fractions.json", import.meta.url),
    "utf8",
  ),
) as Record<string, string>;

const bumped = [
  "compare-fractions-reason-blanks",
  "equivalent-numerator",
  "improper-fractional-part",
  "improper-whole-part",
  "like-fraction-difference",
  "like-fraction-missing-part",
  "mixed-fraction-difference",
  "mixed-to-improper-numerator",
  "staar-order-decimals",
  "tenths-as-hundredths",
  "whole-times-fraction",
] as const;

const digest = (value: unknown) =>
  createHash("sha256").update(JSON.stringify(value)).digest("hex");

test("generateProblem at version 1 reprints the stored fraction problem", () => {
  assert.deepEqual(Object.keys(legacyGolden).sort(), [...bumped].sort());
  for (const id of bumped) {
    const meta = templates.find((t) => t.id === id);
    assert.ok(meta, id);
    assert.equal(meta.version, 2, id);
    assert.equal(meta.reprintsFrom, 1, id);
    const rows: string[] = [];
    for (let i = 0; i < 200; i++) {
      const seed = `gate-legacy:${i}`;
      rows.push(digest(generateProblem(id, seed, 1)));
      assert.equal(
        digest(generateProblem(id, seed, meta.version)),
        digest(generateProblem(id, seed)),
        `${id} ${seed} current`,
      );
    }
    assert.equal(
      createHash("sha256").update(rows.join("\n")).digest("hex").slice(0, 32),
      legacyGolden[id],
      `${id}: version 1 no longer reprints the stored problems`,
    );
  }
});
